a {
  color: var(--ac-dark);
  text-decoration: underline;
  text-decoration-thickness: 3px;
  text-decoration-color: var(--ac-yellow);
  text-underline-offset: 3px;
  transition: all 0.2s ease;
}
a:hover {
  background-color: var(--ac-yellow);
  color: var(--ac-dark);
  text-decoration: none;
}

.hero-section {
  border-bottom: 3px solid var(--ac-dark);
  padding: 6rem 0;
  background-image: radial-gradient(var(--ac-dark) 1px, transparent 1px);
  background-size: 30px 30px;
  background-position: center;
}
.hero-section h1, .hero-section h2 {
  font-size: clamp(3rem, 8vw, 5.5rem);
  line-height: 1;
  letter-spacing: -3px;
  font-weight: 700;
  background-color: var(--ac-bg);
  display: inline-block;
  padding: 0 15px;
}
.hero-section p {
  font-size: 1.25rem;
  font-weight: 500;
  max-width: 600px;
  margin: 1.5rem auto;
  background-color: var(--ac-bg);
  padding: 10px;
}

.contact-form-button {
  background: var(--ac-yellow) !important;
  color: var(--ac-dark) !important;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.1rem;
  border: none !important;
  padding: 12px !important;
  cursor: pointer;
  text-transform: uppercase;
  box-shadow: 4px 4px 0 #fff;
  transition: transform 0.1s, box-shadow 0.1s;
}
.contact-form-button:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 #fff; }
.contact-form-button:active { transform: translate(4px, 4px); box-shadow: 0 0 0 #fff; }

.contact-form-name, .contact-form-email, .contact-form-email-message { width: 100%; padding: 12px 15px; background: transparent; border: 2px solid #333; color: var(--ac-bg); font-family: var(--font-mono); font-size: 0.9rem; outline: none; border-radius: 0; transition: border-color 0.3s ease; }
.contact-form-name::placeholder, .contact-form-email::placeholder, .contact-form-email-message::placeholder { color: #666; }
.contact-form-name:focus, .contact-form-email:focus, .contact-form-email-message:focus { border-color: var(--ac-yellow); background: rgba(255,255,255,0.05); }

.footer-section { background-color: var(--ac-dark); color: var(--ac-bg); border-top: 5px solid var(--ac-yellow); }
.footer-section h2, .footer-section h3 { color: var(--ac-yellow); text-transform: uppercase; border-bottom: 2px solid #333; padding-bottom: 10px; }
.footer-section a { color: var(--ac-bg); text-decoration-color: #555; }
.footer-section a:hover { color: var(--ac-dark); background-color: var(--ac-yellow); text-decoration: none; }
.footer-bottom { border-top: 1px solid #333 !important; font-family: var(--font-mono); font-size: 0.8rem; color: #888; }

.post-title-single { font-size: clamp(2.5rem, 5vw, 4rem); line-height: 1; margin-bottom: 1rem; }
.post-body-content { font-size: 1.2rem; line-height: 1.8; margin-top: 2rem; }
.post-body-content img { max-width: 100%; height: auto; border: 3px solid var(--ac-dark); margin: 1.5rem 0; box-shadow: 8px 8px 0 var(--ac-dark); }

.ac-hero-strip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  background: var(--ac-dark);
  border: 3px solid var(--ac-dark);
  padding: 14px 20px;
  margin-bottom: 1.5rem;
  text-align: center;
}
.ac-hero-strip-badge {
  background: var(--ac-yellow);
  color: var(--ac-dark);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.75rem;
  text-transform: uppercase;
  padding: 4px 10px;
  letter-spacing: 1px;
}
.ac-hero-strip p {
  color: var(--ac-bg);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1rem;
  margin: 0;
}

