.ac-hero-strip--ticker {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 14px;
  flex-wrap: wrap;
  width: 100%;
  background: var(--ac-dark);
  border-bottom: 4px solid var(--ac-yellow);
  padding: 12px 20px;
  margin-bottom: 1.5rem;
  text-align: left;
}
.ac-hero-strip--ticker .ac-hero-strip-badge {
  background: var(--ac-yellow);
  color: var(--ac-dark);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.75rem;
  text-transform: uppercase;
  padding: 4px 10px;
  letter-spacing: 1px;
}
.ac-hero-strip-arrow {
  color: var(--ac-yellow);
  font-family: var(--font-mono);
  font-weight: 700;
}
.ac-hero-strip--ticker p {
  color: var(--ac-bg);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1rem;
  margin: 0;
}

.ac-hero-strip--stacked {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin: 0 auto 1.5rem;
  background: var(--ac-yellow);
  border: 3px solid var(--ac-dark);
  box-shadow: 6px 6px 0 var(--ac-dark);
  padding: 16px 22px;
  text-align: center;
}
.ac-hero-strip--stacked .ac-hero-strip-badge {
  background: var(--ac-dark);
  color: var(--ac-yellow);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.75rem;
  text-transform: uppercase;
  padding: 4px 10px;
  letter-spacing: 1px;
}
.ac-hero-strip--stacked p {
  color: var(--ac-dark);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1rem;
  margin: 0;
}

.ac-hero-strip--outline {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  margin: 20px auto 1.5rem;
  background: transparent;
  border: 3px solid var(--ac-yellow);
  padding: 18px 22px 14px;
  text-align: center;
}
.ac-hero-strip--outline .ac-hero-strip-badge {
  position: absolute;
  top: -14px;
  left: 16px;
  background: var(--ac-yellow);
  color: var(--ac-dark);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.7rem;
  text-transform: uppercase;
  padding: 3px 8px;
  letter-spacing: 1px;
  clip-path: polygon(0 0, 100% 0, 92% 100%, 8% 100%);
}
.ac-hero-strip--outline p {
  color: var(--ac-dark);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1rem;
  margin: 0;
}

.ac-hero-strip--split {
  display: flex;
  align-items: stretch;
  width: fit-content;
  margin: 0 auto 1.5rem;
}
.ac-hero-strip--split .ac-hero-strip-badge {
  display: flex;
  align-items: center;
  background: var(--ac-dark);
  color: var(--ac-yellow);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.75rem;
  text-transform: uppercase;
  padding: 12px 16px;
  letter-spacing: 1px;
}
.ac-hero-strip--split p {
  display: flex;
  align-items: center;
  background: var(--ac-yellow);
  color: var(--ac-dark);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1rem;
  margin: 0;
  padding: 12px 18px;
}
